CREATE TABLE canonical_ticket(id serial PRIMARY KEY,payload integer);
INSERT INTO canonical_ticket(payload) VALUES(1) RETURNING id;
ALTER SEQUENCE canonical_ticket_id_seq OWNED BY NONE;
TRUNCATE canonical_ticket RESTART IDENTITY;
INSERT INTO canonical_ticket(payload) VALUES(2) RETURNING id;
SELECT pg_get_serial_sequence('canonical_ticket','id') IS NULL;
CREATE SCHEMA canonical_counters;
ALTER SEQUENCE canonical_ticket_id_seq RENAME TO ticket_counter;
ALTER SEQUENCE ticket_counter SET SCHEMA canonical_counters;
ALTER TABLE canonical_ticket RENAME TO canonical_order;
ALTER TABLE canonical_order RENAME COLUMN id TO ticket;
INSERT INTO canonical_order(payload) VALUES(3) RETURNING ticket;
SELECT pg_get_expr(adbin,adrelid) FROM pg_attrdef WHERE adrelid='canonical_order'::regclass;
ALTER TABLE canonical_order ALTER COLUMN ticket SET DEFAULT 99;
UPDATE canonical_order SET ticket=DEFAULT WHERE payload=3 RETURNING ticket;
ALTER TABLE canonical_order ALTER COLUMN ticket DROP DEFAULT;
INSERT INTO canonical_order(payload) VALUES(4);
DROP TABLE canonical_order;
DROP SEQUENCE canonical_counters.ticket_counter;
DROP SCHEMA canonical_counters;

CREATE TABLE canonical_restart(id serial);
SELECT nextval('canonical_restart_id_seq');
ALTER TABLE canonical_restart ALTER COLUMN id DROP DEFAULT;
TRUNCATE canonical_restart RESTART IDENTITY;
SELECT nextval('canonical_restart_id_seq');
ALTER SEQUENCE canonical_restart_id_seq OWNED BY NONE;
SELECT setval('canonical_restart_id_seq',41,true);
TRUNCATE canonical_restart RESTART IDENTITY;
SELECT nextval('canonical_restart_id_seq');
ALTER SEQUENCE canonical_restart_id_seq OWNED BY canonical_restart.id;
TRUNCATE canonical_restart RESTART IDENTITY;
SELECT nextval('canonical_restart_id_seq');
DROP TABLE canonical_restart;

CREATE TABLE canonical_drop(id serial);
CREATE TABLE canonical_copy(LIKE canonical_drop INCLUDING DEFAULTS);
ALTER SEQUENCE canonical_drop_id_seq OWNED BY NONE;
SELECT count(*) FROM pg_depend WHERE classid=2604 AND refobjid='canonical_drop_id_seq'::regclass AND deptype='n';
DROP SEQUENCE canonical_drop_id_seq;
DROP SEQUENCE canonical_drop_id_seq CASCADE;
CREATE SEQUENCE canonical_drop_id_seq START WITH 100;
SELECT column_default IS NULL FROM information_schema.columns
  WHERE table_name IN('canonical_drop','canonical_copy') AND column_name='id' ORDER BY table_name;
INSERT INTO canonical_drop DEFAULT VALUES;
ALTER TABLE canonical_drop ALTER COLUMN id SET DEFAULT nextval('canonical_drop_id_seq');
INSERT INTO canonical_drop DEFAULT VALUES RETURNING id;
DROP TABLE canonical_copy,canonical_drop;
DROP SEQUENCE canonical_drop_id_seq;

CREATE TABLE canonical_backfill(payload integer);
INSERT INTO canonical_backfill VALUES(10),(20);
ALTER TABLE canonical_backfill ADD COLUMN id serial;
ALTER TABLE canonical_backfill ADD COLUMN identity_value bigint GENERATED ALWAYS AS IDENTITY(START WITH 7 INCREMENT BY 3);
SELECT id,identity_value,payload FROM canonical_backfill ORDER BY id;
INSERT INTO canonical_backfill(payload) VALUES(30) RETURNING id,identity_value;
SELECT pg_get_serial_sequence('canonical_backfill','id'),pg_get_serial_sequence('canonical_backfill','identity_value');
ALTER TABLE canonical_backfill ALTER COLUMN identity_value SET DEFAULT 99;
ALTER TABLE canonical_backfill ALTER COLUMN identity_value DROP DEFAULT;
DROP TABLE canonical_backfill;
